boltOn.example:
t3template.addControl({ id: 'warmth', label: 'Amount', type: 'slider', min: 0, max: 1, step: 0.01, default: 0.35, panel: 'Tint' });
t3template.addControl({ id: 'tint', label: 'Colour', type: 'color', default: '#ff9a3c', panel: 'Tint' });
t3template.addShaderStage('tint', `uniform float u_amount;
uniform vec3 u_tint;
void main() {
  vec4 c = texture2D(u_image, v_uv);
  gl_FragColor = vec4(mix(c.rgb, c.rgb * u_tint * 1.4, u_amount), c.a);
}`, (c) => ({ u_amount: c.warmth, u_tint: c.tint }));
t3template.addControl({ id: 'caption', label: 'Caption', type: 'text', default: 'Sonoma, spring', panel: 'Caption' });
t3template.addControl({ id: 'frame', label: 'Frame', type: 'color', default: '#ffffff', panel: 'Caption' });
t3template.addImageStage('caption', ({ context, width, height, output }, c) => {
  const edge = Math.round(Math.min(width, height) * 0.02);
  context.strokeStyle = c.frame;
  context.lineWidth = edge * 2;
  context.strokeRect(0, 0, width, height);
  if (!c.caption) return;
  context.fillStyle = c.frame;
  context.font = `600 ${Math.round(height * 0.04)}px sans-serif`;
  context.textAlign = 'center';
  context.fillText(c.caption, width / 2, height * (1 - output.safe.bottom) - edge * 2);
}, { at: 'output' });
t3template.addPlatform({ id: 'pinterest', name: 'Pinterest Pin', short: 'Pin', aspect: '2:3', width: 1000 });
t3template.addToolbarButton('Tint Off', (t) => t.setValues({ controls: { warmth: 0 } }), { shortcut: 't' });
